  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "CI",
      "years": [
        2015,
        2024
      ],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "A/E range 0.731-1.100; observed yearly SD about 0.13 vs baseline Poisson SD about 0.03. Low 2017-2019 (A/E 0.927/0.808/0.731, about -541 claims cumulative) offset by 2020-2024 excess (A/E 1.067/1.100/1.084/1.090/1.055, about +612 claims).",
      "confidence": 0.85,
      "evidence": [
        "summary.json: CI overall A/E=1.0143, so the full-period level is close to 1 despite large annual swings.",
        "artifacts/ae_ci_by_year.csv: yearly Actual/Expected are 627/596, 791/720, 776/837, 778/963, 802/1097, 1322/1239, 1525/1386, 1679/1548, 1873/1719, 1998/1893.",
        "The annual A/E standard deviation and range are much larger than sampling noise for expected counts of roughly 600-1900, where 1/sqrt(Expected) is about 0.02-0.04."
      ],
      "recommended_action": "Investigate timing/data completeness and CI mix for 2017-2024, especially the 2017-2019 undercount followed by the 2020-2024 excess (possible reporting lag, claims-process event, or definition change). Split the experience into sub-periods before setting central rates; if no level bias remains after reconciliation, review volatility/process-risk assumptions and pricing/reserving margins."
    }
  ]
}

